-- Milestone 3: stores, integrations, credentials, sync, webhooks, customers, orders
CREATE TYPE "StorePlatform" AS ENUM ('WOOCOMMERCE','SHOPIFY','CUSTOM');
CREATE TYPE "IntegrationStatus" AS ENUM ('CONNECTED','DISCONNECTED','ERROR');
CREATE TYPE "SyncJobStatus" AS ENUM ('RUNNING','COMPLETED','FAILED');
CREATE TABLE "Store" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "platform" "StorePlatform" NOT NULL DEFAULT 'WOOCOMMERCE', "name" TEXT NOT NULL, "url" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'BDT', "timezone" TEXT NOT NULL DEFAULT 'Asia/Dhaka', "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Store_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Store_organizationId_idx" ON "Store"("organizationId");
CREATE TABLE "Integration" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "storeId" TEXT, "provider" TEXT NOT NULL, "status" "IntegrationStatus" NOT NULL DEFAULT 'DISCONNECTED', "externalAccountId" TEXT, "lastSyncAt" TIMESTAMP(3), "productsCursor" TIMESTAMP(3), "ordersCursor" TIMESTAMP(3), "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Integration_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Integration_organizationId_provider_idx" ON "Integration"("organizationId","provider");
CREATE INDEX "Integration_storeId_idx" ON "Integration"("storeId");
CREATE TABLE "IntegrationCredential" ("id" TEXT NOT NULL, "integrationId" TEXT NOT NULL, "encryptedData" TEXT NOT NULL, "keyVersion" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "IntegrationCredential_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "IntegrationCredential_integrationId_key" ON "IntegrationCredential"("integrationId");
CREATE TABLE "SyncJob" ("id" TEXT NOT NULL, "integrationId" TEXT NOT NULL, "kind" TEXT NOT NULL, "status" "SyncJobStatus" NOT NULL DEFAULT 'RUNNING', "fetched" INTEGER NOT NULL DEFAULT 0, "created" INTEGER NOT NULL DEFAULT 0, "updated" INTEGER NOT NULL DEFAULT 0, "skipped" INTEGER NOT NULL DEFAULT 0, "error" TEXT, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), CONSTRAINT "SyncJob_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SyncJob_integrationId_startedAt_idx" ON "SyncJob"("integrationId","startedAt");
CREATE TABLE "WebhookEvent" ("id" TEXT NOT NULL, "integrationId" TEXT NOT NULL, "provider" TEXT NOT NULL, "topic" TEXT, "deliveryId" TEXT, "payload" JSONB NOT NULL, "signatureValid" BOOLEAN NOT NULL DEFAULT false, "processedAt" TIMESTAMP(3), "error" TEXT, "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WebhookEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WebhookEvent_integrationId_deliveryId_key" ON "WebhookEvent"("integrationId","deliveryId");
CREATE INDEX "WebhookEvent_integrationId_receivedAt_idx" ON "WebhookEvent"("integrationId","receivedAt");
CREATE TABLE "Customer" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "externalId" TEXT, "source" TEXT NOT NULL DEFAULT 'woocommerce', "firstName" TEXT, "lastName" TEXT, "email" TEXT, "phone" TEXT, "address" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Customer_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Customer_organizationId_email_idx" ON "Customer"("organizationId","email");
CREATE INDEX "Customer_organizationId_phone_idx" ON "Customer"("organizationId","phone");
CREATE INDEX "Customer_organizationId_externalId_idx" ON "Customer"("organizationId","externalId");
CREATE TABLE "Order" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "storeId" TEXT, "customerId" TEXT, "externalId" TEXT NOT NULL, "externalNumber" TEXT, "source" TEXT NOT NULL DEFAULT 'woocommerce', "status" TEXT NOT NULL, "paymentMethod" TEXT, "isCod" BOOLEAN NOT NULL DEFAULT false, "currency" TEXT NOT NULL DEFAULT 'BDT', "subtotalMinor" BIGINT NOT NULL DEFAULT 0, "shippingMinor" BIGINT NOT NULL DEFAULT 0, "discountMinor" BIGINT NOT NULL DEFAULT 0, "taxMinor" BIGINT NOT NULL DEFAULT 0, "totalMinor" BIGINT NOT NULL DEFAULT 0, "refundedMinor" BIGINT NOT NULL DEFAULT 0, "placedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Order_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Order_organizationId_source_externalId_key" ON "Order"("organizationId","source","externalId");
CREATE INDEX "Order_organizationId_status_idx" ON "Order"("organizationId","status");
CREATE INDEX "Order_organizationId_placedAt_idx" ON "Order"("organizationId","placedAt");
CREATE TABLE "OrderItem" ("id" TEXT NOT NULL, "orderId" TEXT NOT NULL, "productId" TEXT, "externalProductId" TEXT, "externalVariationId" TEXT, "name" TEXT NOT NULL, "sku" TEXT, "quantity" INTEGER NOT NULL, "priceMinor" BIGINT NOT NULL DEFAULT 0, "totalMinor" BIGINT NOT NULL DEFAULT 0, CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id"));
CREATE INDEX "OrderItem_orderId_idx" ON "OrderItem"("orderId");
CREATE INDEX "OrderItem_productId_idx" ON "OrderItem"("productId");
ALTER TABLE "Store" ADD CONSTRAINT "Store_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Integration" ADD CONSTRAINT "Integration_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Integration" ADD CONSTRAINT "Integration_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "IntegrationCredential" ADD CONSTRAINT "IntegrationCredential_integrationId_fkey" FOREIGN KEY ("integrationId") REFERENCES "Integration"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SyncJob" ADD CONSTRAINT "SyncJob_integrationId_fkey" FOREIGN KEY ("integrationId") REFERENCES "Integration"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WebhookEvent" ADD CONSTRAINT "WebhookEvent_integrationId_fkey" FOREIGN KEY ("integrationId") REFERENCES "Integration"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Customer" ADD CONSTRAINT "Customer_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
